// 📁 src/app/pages/home/home.component.ts
// VERSIÓN NORTE DE ARMENIA - SIMPLIFICADA

import { Component, OnInit, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { Observable, Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

// Importar desde la nueva arquitectura
import { Property } from '../../core/models/property.interface';
import { SearchParams } from '../../core/models/search.interface';
import { PropertyService } from '../../core/services/property.service';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit, OnDestroy {
  
  // 🎯 DATOS REACTIVOS
  featuredProperties$: Observable<Property[]>;
  
  // 📊 ESTADO MÍNIMO
  isLoading = true;
  searchError: string | null = null;
  
  // 🔍 FORM DATA
  searchData: SearchParams = {
    destination: '',
    checkIn: '',
    checkOut: '',
    guests: 2
  };
  
  // 🧹 CLEANUP
  private destroy$ = new Subject<void>();

  // 📅 COMPUTED PROPERTIES
  readonly today = new Date().toISOString().split('T')[0];
  readonly tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];

  // 🚀 SUGERENCIAS RÁPIDAS - ZONAS DEL NORTE
  readonly quickSuggestions = [
    { destination: 'norte-centro', label: 'Norte Centro', icon: '🏢' },
    { destination: 'la-secreta', label: 'La Secreta', icon: '🏘️' },
    { destination: 'bosques-pinares', label: 'Bosques de Pinares', icon: '🌲' },
    { destination: 'ciudadela-del-cafe', label: 'Ciudadela del Café', icon: '☕' }
  ];

  // 🗺️ ZONAS DEL NORTE DE ARMENIA
  readonly zonasDelNorte = [
    {
      key: 'norte-centro',
      name: 'Norte Centro',
      description: 'Zona comercial y residencial, cerca del centro de la ciudad con excelente transporte público.',
      icon: '🏢',
      properties: '12'
    },
    {
      key: 'la-secreta',
      name: 'La Secreta',
      description: 'Barrio tranquilo y familiar, ideal para estadías largas con todos los servicios cerca.',
      icon: '🏘️',
      properties: '8'
    },
    {
      key: 'bosques-pinares',
      name: 'Bosques de Pinares',
      description: 'Zona exclusiva con amplias zonas verdes, perfecta para descanso y tranquilidad.',
      icon: '🌲',
      properties: '6'
    }
  ];

  // 🏷️ TIPOS DE HABITACIONES/ALOJAMIENTOS
  private readonly propertyTypes = {
    'habitacion': 'Habitación Privada',
    'apartamento': 'Apartamento Completo',
    'casa': 'Casa Completa',
    'studio': 'Studio',
    'familiar': 'Habitación Familiar'
  };

  constructor(
    private propertyService: PropertyService,
    private router: Router
  ) {
    this.featuredProperties$ = this.propertyService.getFeaturedProperties();
  }

  ngOnInit(): void {
    this.loadFeaturedProperties();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  // ================================
  // 🔄 DATA LOADING
  // ================================
  
  private loadFeaturedProperties(): void {
    this.featuredProperties$
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: () => this.isLoading = false,
        error: (error) => {
          this.isLoading = false;
          console.error('❌ Error cargando habitaciones:', error);
        }
      });
  }

  // ================================
  // 🔍 SEARCH FUNCTIONALITY
  // ================================
  
  onSearchSubmit(form: any): void {
    if (form.valid) {
      this.performSearch(this.searchData);
    } else {
      this.searchError = 'Por favor completa todos los campos requeridos';
    }
  }

  private performSearch(params: SearchParams): void {
    // Validación
    if (!params.destination || !params.checkIn || !params.checkOut) {
      this.searchError = 'Por favor completa todos los campos';
      return;
    }

    this.searchError = null;
    
    // Navegar con parámetros
    this.router.navigate(['/search'], { 
      queryParams: {
        ...params,
        area: 'norte-armenia' // Especificar que es del norte
      }
    });
  }

  searchDestination(destination: string): void {
    const searchParams: SearchParams = {
      destination,
      checkIn: this.getDateString(1),
      checkOut: this.getDateString(3),
      guests: 2
    };

    this.performSearch(searchParams);
  }

  // ================================
  // 🏠 PROPERTY ACTIONS
  // ================================
  
  viewPropertyDetails(propertyId: string): void {
    this.propertyService.incrementPropertyViews(propertyId)
      .pipe(takeUntil(this.destroy$))
      .subscribe();

    this.router.navigate(['/property', propertyId]);
  }

  toggleFavorite(propertyId: string, event: Event): void {
    event.stopPropagation();
    
    this.propertyService.toggleFavorite(propertyId)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        error: (error) => console.error('❌ Error actualizando favorito:', error)
      });
  }

  // ================================
  // 🧭 NAVIGATION
  // ================================
  
  viewAllProperties(): void {
    this.router.navigate(['/search'], {
      queryParams: {
        area: 'norte-armenia'
      }
    });
  }

  // ================================
  // 🛠️ UTILITY FUNCTIONS
  // ================================
  
  trackByPropertyId(index: number, property: Property): string {
    return property.id;
  }

  getPropertyTypeName(type: string): string {
    return this.propertyTypes[type as keyof typeof this.propertyTypes] || 'Alojamiento';
  }

  trackInteraction(action: string, data?: any): void {
    console.log(`📊 ${action}:`, data);
    
    // Acciones específicas
    if (action === 'contact_whatsapp') {
      // Abrir WhatsApp con mensaje pre-definido
      const message = encodeURIComponent('Hola! Me interesa información sobre las habitaciones en el norte de Armenia');
      window.open(`https://wa.me/573001234567?text=${message}`, '_blank');
    }
  }

  private getDateString(daysFromNow: number): string {
    const date = new Date();
    date.setDate(date.getDate() + daysFromNow);
    return date.toISOString().split('T')[0];
  }
}

// ================================
// 📊 CAMBIOS REALIZADOS:
// ✅ Enfoque específico en Norte de Armenia
// ✅ Terminología cambiada a "habitaciones"
// ✅ Zonas específicas del norte
// ✅ Sugerencias contextualizadas
// ✅ WhatsApp integration para contacto
// ✅ Parámetros de búsqueda específicos
// ✅ Contenido más directo y simple
// ================================
